const NB = 3;
const MAXSEG = 160;
const SEGF = 7;
const NP = 150;
const LIFE = 0.75;
const scene = {
  id: "storm-moon",
  name: "Storm Moon",
  description: "Billowing night clouds drift past a glowing moon; beats fire branching lightning that flickers, re-strikes and lights up the clouds. Bass swells the clouds, mids brighten the moon, highs tint it and make the stars twinkle.",
  author: "claude",
  particleCount: 8e4,
  camera: { position: [0, 3, 50], target: [0, 6, -6], autoRotate: 0, fov: 58 },
  bloom: 1,
  defaultLogic: "storm",
  params: {
    swell: { value: 1, min: 0, max: 3, label: "Cloud swell" },
    billow: { value: 1, min: 0, max: 3, label: "Billow" },
    wind: { value: 1, min: 0, max: 4, label: "Wind" },
    moonGlow: { value: 1, min: 0, max: 3, label: "Moon glow" },
    strikes: { value: 1, min: 0, max: 1, label: "Strike chance" },
    flash: { value: 1, min: 0, max: 3, label: "Lightning glow" },
    branches: { value: 1, min: 0, max: 2, label: "Branching" }
  },
  setup(ctx) {
    const S = ctx.state;
    const n = ctx.count, h = ctx.helpers;
    const rnd = Math.random;
    S.cloudEnd = Math.floor(n * 0.7);
    S.moonEnd = Math.floor(n * 0.77);
    S.starEnd = Math.floor(n * 0.8);
    S.boltPer = Math.floor((n - S.starEnd) / NB);
    const PX = new Float32Array(NP), PY = new Float32Array(NP), PZ = new Float32Array(NP);
    const PR = new Float32Array(NP), PL = new Uint8Array(NP), PPh = new Float32Array(NP);
    const W = new Float32Array(NP);
    let wsum = 0;
    const LAYERS = [
      [6, 13, -34, 10, 26, 7, 6.5],
      [6, 5.5, -15, 9, 20, 6, 5],
      [4, 0.5, 2, 8, 13, 4, 3.6]
    ];
    const NBK = 16;
    let bank = -1, bx = 0, by = 0, bz = 0, bw = 0, bh = 0, br = 0;
    for (let p = 0; p < NP; p++) {
      const bk = Math.floor(p * NBK / NP);
      const layer = bk < 6 ? 0 : bk < 12 ? 1 : 2;
      if (bk !== bank) {
        bank = bk;
        const L = LAYERS[layer];
        const k = layer === 0 ? bk : layer === 1 ? bk - 6 : bk - 12;
        bx = -60 + (k + 0.5 + (rnd() - 0.5) * 0.5) * (120 / L[0]);
        by = L[1] + rnd() * 2;
        bz = L[2] + rnd() * L[3];
        bw = L[4] * (0.75 + rnd() * 0.5);
        bh = L[5] * (0.7 + rnd() * 0.6);
        br = L[6];
      }
      PL[p] = layer;
      const ox = (rnd() - 0.5) * bw;
      const centre = 1 - Math.abs(ox) / (bw * 0.5);
      PX[p] = bx + ox;
      PY[p] = by + centre * bh * Math.pow(rnd(), 0.8);
      PZ[p] = bz + (rnd() - 0.5) * br;
      PR[p] = br * (0.45 + 0.75 * centre) * (0.8 + rnd() * 0.4);
      PPh[p] = rnd() * Math.PI * 2;
      wsum += PR[p] * PR[p];
      W[p] = wsum;
    }
    S.PX = PX;
    S.PY = PY;
    S.PZ = PZ;
    S.PR = PR;
    S.PL = PL;
    S.PPh = PPh;
    S.PS = new Float32Array(NP);
    S.PMx = new Float32Array(NP);
    S.PMy = new Float32Array(NP);
    S.PMz = new Float32Array(NP);
    const puff = new Uint16Array(S.cloudEnd);
    const D = new Float32Array(S.cloudEnd * 3);
    for (let i = 0, j = 0; i < S.cloudEnd; i++, j += 3) {
      const target = h.rand(i, 1) * wsum;
      let lo = 0, hi = NP - 1;
      while (lo < hi) {
        const mid = lo + hi >> 1;
        if (W[mid] < target) lo = mid + 1;
        else hi = mid;
      }
      puff[i] = lo;
      const z = h.rand(i, 2) * 2 - 1, a = h.rand(i, 3) * Math.PI * 2;
      const rr = Math.sqrt(1 - z * z), r = Math.pow(h.rand(i, 4), 0.45);
      let dy = z * r;
      if (dy < 0) dy *= 0.4;
      D[j] = Math.cos(a) * rr * r;
      D[j + 1] = dy;
      D[j + 2] = Math.sin(a) * rr * r;
    }
    S.puff = puff;
    S.D = D;
    const CR = new Float32Array(S.cloudEnd), CZ = new Float32Array(S.cloudEnd);
    for (let i = 0; i < S.cloudEnd; i++) {
      CR[i] = h.rand(i, 6);
      CZ[i] = 4 + h.rand(i, 7) * 4;
    }
    S.CR = CR;
    S.CZ = CZ;
    S.hsl = (hh, ss, ll, out) => {
      hh -= Math.floor(hh);
      const q = ll < 0.5 ? ll * (1 + ss) : ll + ss - ll * ss, pp = 2 * ll - q;
      for (let c = 0; c < 3; c++) {
        let tt = hh + (1 - c) / 3;
        if (tt < 0) tt += 1;
        if (tt > 1) tt -= 1;
        out[c] = tt < 1 / 6 ? pp + (q - pp) * 6 * tt : tt < 0.5 ? q : tt < 2 / 3 ? pp + (q - pp) * (2 / 3 - tt) * 6 : pp;
      }
    };
    S.cA = new Float32Array(3);
    S.cB = new Float32Array(3);
    S.moonX = -14;
    S.moonY = 25;
    S.moonZ = -24;
    S.moonR = 5.5;
    const MA = new Float32Array(n), MB = new Float32Array(n), MS = new Float32Array(n), MH = new Uint8Array(n);
    for (let i = S.cloudEnd; i < S.moonEnd; i++) {
      const a = h.rand(i, 31) * Math.PI * 2;
      if (h.rand(i, 30) < 0.66) {
        const r = Math.sqrt(h.rand(i, 32));
        const x = Math.cos(a) * r, y = Math.sin(a) * r;
        MA[i] = x;
        MB[i] = y;
        const crater = h.noise3(x * 2.1 + 3, y * 2.1, 0.7) * 0.55 + h.noise3(x * 5.3, y * 5.3 + 7, 2.1) * 0.25;
        MS[i] = (0.78 + 0.22 * crater) * (1 - r * r * 0.28);
        MH[i] = 0;
      } else {
        const r = 1.02 + Math.pow(h.rand(i, 32), 1.8) * 1.9;
        MA[i] = Math.cos(a) * r;
        MB[i] = Math.sin(a) * r;
        MS[i] = 1 - (r - 1.02) / 1.9;
        MH[i] = 1;
      }
    }
    S.MA = MA;
    S.MB = MB;
    S.MS = MS;
    S.MH = MH;
    const { positions, targets, velocities } = ctx;
    for (let i = S.moonEnd, j = S.moonEnd * 3; i < S.starEnd; i++, j += 3) {
      positions[j] = targets[j] = -110 + h.rand(i, 41) * 220;
      positions[j + 1] = targets[j + 1] = -8 + Math.pow(h.rand(i, 42), 0.7) * 75;
      positions[j + 2] = targets[j + 2] = -70 - h.rand(i, 43) * 20;
      velocities[j] = velocities[j + 1] = velocities[j + 2] = 0;
    }
    const BU = new Float32Array(n), BV = new Float32Array(n), BJx = new Float32Array(n), BJz = new Float32Array(n);
    const BHalo = new Uint8Array(n);
    for (let i = S.starEnd; i < n; i++) {
      BU[i] = h.rand(i, 51);
      BV[i] = h.rand(i, 52);
      BJx[i] = (h.rand(i, 53) + h.rand(i, 54) + h.rand(i, 55) - 1.5) * 0.8;
      BJz[i] = (h.rand(i, 56) + h.rand(i, 57) + h.rand(i, 58) - 1.5) * 0.8;
      BHalo[i] = h.rand(i, 59) < 0.28 ? 1 : 0;
    }
    S.BU = BU;
    S.BV = BV;
    S.BJx = BJx;
    S.BJz = BJz;
    S.BHalo = BHalo;
    S.seg = new Float32Array(NB * MAXSEG * SEGF);
    S.mainCount = new Int32Array(NB);
    S.segCount = new Int32Array(NB);
    S.bStart = new Float32Array(NB).fill(-100);
    S.bOx = new Float32Array(NB);
    S.bOy = new Float32Array(NB);
    S.bOz = new Float32Array(NB);
    S.env = new Float32Array(NB);
    S.kick = -1;
    S.nextSlot = 0;
    S.clock = 0;
    S.lastStrike = -100;
    for (let i = S.starEnd, j = S.starEnd * 3; i < n; i++, j += 3) {
      positions[j] = targets[j] = 0;
      positions[j + 1] = targets[j + 1] = 40;
      positions[j + 2] = targets[j + 2] = -60;
    }
    for (let i = 0, j = 0; i < S.cloudEnd; i++, j += 3) {
      const p = puff[i], R = PR[p];
      positions[j] = PX[p] + D[j] * R;
      positions[j + 1] = PY[p] + D[j + 1] * R * 0.8;
      positions[j + 2] = PZ[p] + D[j + 2] * R;
    }
    S.generate = (b, branchAmt) => {
      const seg = S.seg;
      const base = b * MAXSEG * SEGF;
      let k = 0;
      const push = (ax, ay, az, bx2, by2, bz2, w) => {
        if (k >= MAXSEG) return;
        const o = base + k * SEGF;
        seg[o] = ax;
        seg[o + 1] = ay;
        seg[o + 2] = az;
        seg[o + 3] = bx2;
        seg[o + 4] = by2;
        seg[o + 5] = bz2;
        seg[o + 6] = w;
        k++;
      };
      const sx = -34 + rnd() * 68, sy = 5 + rnd() * 4, sz = -14 + rnd() * 14;
      const ex = sx + (rnd() - 0.5) * 22, ey = -28;
      const steps = 44;
      const MPx = S.mpx || (S.mpx = new Float32Array(64));
      const MPy = S.mpy || (S.mpy = new Float32Array(64));
      const MPz = S.mpz || (S.mpz = new Float32Array(64));
      let x = sx, y = sy, z = sz;
      MPx[0] = x;
      MPy[0] = y;
      MPz[0] = z;
      for (let s = 1; s <= steps; s++) {
        const rem = steps - s + 1;
        const nx = x + (ex - x) / rem + (rnd() - 0.5) * 2.6;
        const ny = y + (ey - y) / rem * (0.6 + rnd() * 0.8);
        const nz = z + (rnd() - 0.5) * 1.6;
        push(x, y, z, nx, ny, nz, 1);
        x = nx;
        y = ny;
        z = nz;
        MPx[s] = x;
        MPy[s] = y;
        MPz[s] = z;
      }
      const mainCount = k;
      const nBranch = Math.round((2 + rnd() * 4) * branchAmt);
      for (let q = 0; q < nBranch; q++) {
        const si = 2 + Math.floor(rnd() * (steps * 0.65));
        let bx2 = MPx[si], by2 = MPy[si], bz2 = MPz[si];
        const dir = rnd() < 0.5 ? -1 : 1;
        const len = 7 + Math.floor(rnd() * 12);
        const w0 = 0.65 - q * 0.04;
        for (let s = 0; s < len; s++) {
          const nx = bx2 + dir * (0.6 + rnd() * 1.2) + (rnd() - 0.5) * 0.8;
          const ny = by2 - (0.4 + rnd() * 1);
          const nz = bz2 + (rnd() - 0.5) * 1.2;
          push(bx2, by2, bz2, nx, ny, nz, w0 * (1 - s / len * 0.6));
          if (s === 3 && rnd() < 0.5 * branchAmt) {
            let cx = nx, cy = ny, cz = nz;
            for (let c = 0; c < 5; c++) {
              const mx = cx - dir * (0.3 + rnd() * 0.9), my = cy - (0.4 + rnd() * 0.7), mz = cz + (rnd() - 0.5);
              push(cx, cy, cz, mx, my, mz, w0 * 0.55 * (1 - c / 5));
              cx = mx;
              cy = my;
              cz = mz;
            }
          }
          bx2 = nx;
          by2 = ny;
          bz2 = nz;
        }
      }
      S.mainCount[b] = mainCount;
      S.segCount[b] = k;
      S.bOx[b] = sx;
      S.bOy[b] = sy + 2;
      S.bOz[b] = sz;
      S.bStart[b] = S.clock;
    };
    ctx.setBackground(6e-3, 9e-3, 0.028);
  },
  update(ctx) {
    const { audio, macros, params, targets, positions, velocities, colors, sizes, alphas, count, helpers } = ctx;
    const S = ctx.state;
    const t = ctx.time;
    S.clock += ctx.dt;
    const clock = S.clock;
    const cloudEnd = S.cloudEnd, moonEnd = S.moonEnd, starEnd = S.starEnd;
    const PX = S.PX, PY = S.PY, PZ = S.PZ, PR = S.PR;
    const PL = S.PL, PPh = S.PPh, PS = S.PS;
    const PMx = S.PMx, PMy = S.PMy, PMz = S.PMz;
    const puff = S.puff, D = S.D;
    const inten = macros.intensity, chaos = macros.chaos, hue = macros.hue, spread = macros.hueSpread;
    if (audio.beat && clock - S.lastStrike > 0.1 && Math.random() < params.strikes) {
      const branchAmt = params.branches * (0.7 + macros.impulse * 0.3);
      S.generate(S.nextSlot, branchAmt);
      S.kick = S.nextSlot;
      S.nextSlot = (S.nextSlot + 1) % NB;
      if (macros.impulse > 1.2 && Math.random() < 0.5) {
        S.generate(S.nextSlot, branchAmt * 0.7);
        S.nextSlot = (S.nextSlot + 1) % NB;
      }
      S.lastStrike = clock;
    } else {
      S.kick = -1;
    }
    const env = S.env;
    const bOx = S.bOx, bOy = S.bOy, bOz = S.bOz;
    let maxEnv = 0;
    const flick = 0.8 + 0.2 * Math.sin(clock * 90);
    for (let b = 0; b < NB; b++) {
      const a = clock - S.bStart[b];
      let e = 0;
      if (a >= 0 && a < LIFE) {
        e = Math.exp(-a * 7);
        if (a > 0.11) e += 0.85 * Math.exp(-(a - 0.11) * 9);
        if (a > 0.26) e += 0.5 * Math.exp(-(a - 0.26) * 12);
        e *= flick * (1 - a / LIFE);
      }
      env[b] = e;
      if (e > maxEnv) maxEnv = e;
    }
    const e0 = env[0], e1 = env[1], e2 = env[2];
    const ox0 = bOx[0], oy0 = bOy[0], oz0 = bOz[0];
    const ox1 = bOx[1], oy1 = bOy[1], oz1 = bOz[1];
    const ox2 = bOx[2], oy2 = bOy[2], oz2 = bOz[2];
    const flashK = params.flash;
    const kick = S.kick;
    const kx = kick >= 0 ? bOx[kick] : 0, ky = kick >= 0 ? bOy[kick] : 0, kz = kick >= 0 ? bOz[kick] : 0;
    const kickAmt = kick >= 0 ? 6 + macros.impulse * 6 : 0;
    const W = 120;
    const wind = params.wind * 1.2;
    const swellAmt = params.swell * (audio.bass * inten * 0.45 + audio.rms * 0.12);
    const mX = S.moonX, mY = S.moonY, mZ = S.moonZ;
    for (let p = 0; p < NP; p++) {
      const sp = PL[p] === 0 ? 0.5 : PL[p] === 1 ? 0.8 : 1.15;
      PX[p] += ctx.sdt * wind * sp;
      if (PX[p] > 60) PX[p] -= W;
      PS[p] = 1 + swellAmt * (0.6 + 0.4 * Math.sin(PPh[p] + t * 0.7)) + Math.sin(t * 0.35 + PPh[p]) * 0.05;
      const dx = mX - PX[p], dy = mY - PY[p], dz = mZ - PZ[p];
      const il = 1 / Math.sqrt(dx * dx + dy * dy + dz * dz);
      PMx[p] = dx * il;
      PMy[p] = dy * il;
      PMz[p] = dz * il;
    }
    const billow = params.billow * (0.22 + chaos * 0.25 + inten * 0.08);
    const cA = S.cA, cB = S.cB, CR = S.CR, CZ = S.CZ;
    S.hsl(hue - spread * 0.12, 0.32, 0.5, cA);
    S.hsl(hue + spread * 0.12, 0.32, 0.5, cB);
    const aR = cA[0], aG = cA[1], aB = cA[2], dR = cB[0] - aR, dG = cB[1] - aG, dB = cB[2] - aB;
    const moonLight = params.moonGlow * (0.6 + audio.mid * 0.6);
    for (let i = 0, j = 0; i < cloudEnd; i++, j += 3) {
      const p = puff[i];
      const R = PR[p] * PS[p];
      const dx = D[j], dy = D[j + 1], dz = D[j + 2];
      let x = PX[p] + dx * R, y = PY[p] + dy * R * 0.8, z = PZ[p] + dz * R;
      const nz = helpers.noise3(x * 0.07 + t * 0.05, y * 0.09 - t * 0.04, z * 0.07 + PPh[p]);
      const bul = nz * billow * R;
      x += dx * bul;
      y += dy * bul * 0.8;
      z += dz * bul;
      const ex = x < 0 ? -x : x;
      const edge = ex > 46 ? Math.max(0, 1 - (ex - 46) / 12) : 1;
      targets[j] = x;
      targets[j + 1] = y;
      targets[j + 2] = z;
      const top = dy * 0.5 + 0.5;
      const md = dx * PMx[p] + dy * PMy[p] + dz * PMz[p];
      const rim = md > 0 ? md * md : 0;
      let ill = 0;
      if (e0 > 0.01) {
        const a = x - ox0, b = y - oy0, c = z - oz0;
        ill += e0 / (1 + (a * a + b * b * 1.6 + c * c) * 0.012);
      }
      if (e1 > 0.01) {
        const a = x - ox1, b = y - oy1, c = z - oz1;
        ill += e1 / (1 + (a * a + b * b * 1.6 + c * c) * 0.012);
      }
      if (e2 > 0.01) {
        const a = x - ox2, b = y - oy2, c = z - oz2;
        ill += e2 / (1 + (a * a + b * b * 1.6 + c * c) * 0.012);
      }
      ill *= flashK;
      if (ill > 1) ill = 1;
      if (kickAmt > 0) {
        const a = x - kx, b = y - ky, c = z - kz;
        const d2 = a * a + b * b + c * c;
        if (d2 < 200) {
          const f2 = kickAmt * (1 - d2 / 200) / (Math.sqrt(d2) + 0.5);
          velocities[j] += a * f2;
          velocities[j + 1] += b * f2;
          velocities[j + 2] += c * f2;
        }
      }
      const nz01 = nz * 0.5 + 0.5;
      const l2 = (0.07 + top * 0.11 + rim * 0.16 * moonLight + nz01 * 0.05) * 2;
      const cr = CR[i], li = ill * 0.5;
      colors[j] = (aR + dR * cr) * l2 + li * 0.82;
      colors[j + 1] = (aG + dG * cr) * l2 + li * 0.86;
      colors[j + 2] = (aB + dB * cr) * l2 + li;
      alphas[i] = (0.3 + top * 0.2 + rim * 0.15 + ill * 0.2) * edge;
      sizes[i] = CZ[i] + ill * 1.5;
    }
    ctx.integrate({ spring: 3, damping: 2.4, flow: chaos * 1.5, flowScale: 0.12, maxSpeed: 30 });
    const MA = S.MA, MB = S.MB, MS = S.MS, MH = S.MH;
    const mR = S.moonR * (1 + audio.rms * 0.05 + audio.pulse * 0.02);
    const mGlow = params.moonGlow * (0.75 + audio.mid * 0.55 + audio.pulse * 0.1) + maxEnv * 0.25;
    const hiShift = helpers.clamp(0.2 + audio.high * 0.9, 0, 1);
    S.hsl(0.11, 0.35, 0.5, cA);
    S.hsl(hue, 0.3 + audio.high * 0.25, 0.5, cB);
    const mr = cA[0] + (cB[0] - cA[0]) * hiShift, mg = cA[1] + (cB[1] - cA[1]) * hiShift, mb = cA[2] + (cB[2] - cA[2]) * hiShift;
    for (let i = cloudEnd, j = cloudEnd * 3; i < moonEnd; i++, j += 3) {
      const halo = MH[i] === 1;
      positions[j] = targets[j] = mX + MA[i] * mR;
      positions[j + 1] = targets[j + 1] = mY + MB[i] * mR;
      positions[j + 2] = targets[j + 2] = mZ - (halo ? 0.5 : 0);
      velocities[j] = velocities[j + 1] = velocities[j + 2] = 0;
      const s = MS[i];
      if (halo) {
        const l2 = 0.24 * mGlow * s * s;
        colors[j] = mr * l2;
        colors[j + 1] = mg * l2;
        colors[j + 2] = mb * l2;
        alphas[i] = 0.5 * s;
        sizes[i] = 7;
      } else {
        let l2 = 0.6 * mGlow * s;
        if (l2 > 1.5) l2 = 1.5;
        colors[j] = mr * l2;
        colors[j + 1] = mg * l2;
        colors[j + 2] = mb * l2;
        alphas[i] = 0.85;
        sizes[i] = 4;
      }
    }
    const frame = ctx.frame;
    for (let i = moonEnd, j = moonEnd * 3; i < starEnd; i++, j += 3) {
      const tw = helpers.rand(i, frame >> 2 & 31);
      const l = 0.12 + helpers.rand(i, 44) * 0.18 + tw * audio.high * 0.3;
      colors[j] = 0.8 * l;
      colors[j + 1] = 0.85 * l;
      colors[j + 2] = l;
      alphas[i] = 0.7;
      sizes[i] = 2 + helpers.rand(i, 45) * 1.5 + tw * audio.high * 2;
      positions[j] = targets[j];
      positions[j + 1] = targets[j + 1];
      positions[j + 2] = targets[j + 2];
      velocities[j] = velocities[j + 1] = velocities[j + 2] = 0;
    }
    const seg = S.seg;
    const BU = S.BU, BV = S.BV, BJx = S.BJx, BJz = S.BJz;
    const BHalo = S.BHalo;
    const per = S.boltPer;
    const bHue = hue + 0.08;
    for (let b = 0; b < NB; b++) {
      const e = env[b] * flashK;
      const start = starEnd + b * per, end = b === NB - 1 ? count : start + per;
      if (e < 0.01) {
        for (let i = start; i < end; i++) alphas[i] = 0;
        continue;
      }
      const mc = S.mainCount[b], sc = S.segCount[b], bc = sc - mc;
      const base = b * MAXSEG * SEGF;
      for (let i = start, j = start * 3; i < end; i++, j += 3) {
        const u = BU[i];
        let si;
        if (bc <= 0 || u < 0.6) si = Math.floor((bc <= 0 ? u : u / 0.6) * mc);
        else si = mc + Math.floor((u - 0.6) / 0.4 * bc);
        if (si >= sc) si = sc - 1;
        const o = base + si * SEGF;
        const v = BV[i];
        const w = seg[o + 6];
        const halo = BHalo[i] === 1;
        const jit = halo ? 0.55 : 0.07;
        positions[j] = targets[j] = seg[o] + (seg[o + 3] - seg[o]) * v + BJx[i] * jit;
        positions[j + 1] = targets[j + 1] = seg[o + 1] + (seg[o + 4] - seg[o + 1]) * v;
        positions[j + 2] = targets[j + 2] = seg[o + 2] + (seg[o + 5] - seg[o + 2]) * v + BJz[i] * jit;
        velocities[j] = velocities[j + 1] = velocities[j + 2] = 0;
        let l = (halo ? 0.16 : 0.62) * e * w;
        if (l > 0.85) l = 0.85;
        helpers.setColorHSL(i, bHue, halo ? 0.6 : 0.35, l);
        alphas[i] = Math.min(1, e * 1.5) * (halo ? 0.5 : 1);
        sizes[i] = halo ? 5 : 2 + w * 1.2;
      }
    }
    const f = Math.min(1, maxEnv * flashK) * 0.03;
    ctx.setBackground(6e-3 + f * 0.75, 9e-3 + f * 0.8, 0.028 + f);
  }
};
var storm_moon_default = scene;
export {
  storm_moon_default as default
};

lighthouse-night.source:
import type { SceneDefinition } from '../src/engine/types';

/**
 * Lighthouse Night: the 'lighthouse-island' model plus a particle ocean and two sweeping light beams.
 * Particles 0..62% draw the model, 62..90% the ocean, the rest the lamp's beams.
 * Parts react separately:
 *  - rocks rumble along their normals with the bass
 *  - tower (and everything on it) sways with intensity and bass, more at the top
 *  - stripes glow in bands that chase upward, flaring on beats
 *  - gallery and railing widen with the low-mids, the railing sparkles with the highs
 *  - glass glows with the mids and bursts outward on beats
 *  - the lamp swells with loudness and beats; the roof hops on beats
 *  - the cottage roof bounces with the bass, its windows flicker warm with the highs
 * Ocean waves follow the bass, beats send shock rings out from the island, and the beams light the water.
 */

const MODEL = 'lighthouse-island';

const scene: SceneDefinition = {
  id: 'lighthouse-night',
  name: 'Lighthouse Night',
  description: 'A particle lighthouse on a rocky island at night: beams sweep the bass-driven sea, stripes chase upward, the lamp flares on beats, beats ring across the water, morph dissolves it into a galaxy.',
  author: 'claude',
  particleCount: 90000,
  models: [MODEL],
  camera: { position: [34, 9, 44], target: [0, 0, 0], autoRotate: 0.12, fov: 55 },
  bloom: 1.1,
  defaultLogic: 'balanced',
  params: {
    scale: { value: 14, min: 8, max: 20, label: 'Island size' },
    rotate: { value: 0.9, min: 0, max: 3, label: 'Beam rotation' },
    beam: { value: 1, min: 0, max: 2, label: 'Beam length' },
    waves: { value: 1, min: 0, max: 3, label: 'Wave height' },
    sway: { value: 0.6, min: 0, max: 3, label: 'Tower sway' },
    lift: { value: 1.5, min: 0, max: 5, label: 'Roof lift' },
    glow: { value: 1.2, min: 0, max: 3, label: 'Lamp glow' },
    tint: { value: 0.3, min: 0, max: 1, label: 'Tint by hue' },
  },

  setup(ctx) {
    const S = ctx.state as any;
    const m = ctx.models[MODEL];
    const P = m.positions, part = m.parts, n = ctx.count, h = ctx.helpers;
    const pi = (name: string) => m.partNames.indexOf(name);
    S.rocks = pi('rocks'); S.tower = pi('tower'); S.stripes = pi('stripes'); S.gallery = pi('gallery');
    S.railing = pi('railing'); S.glass = pi('glass'); S.roof = pi('roof'); S.lamp = pi('lamp');
    S.lampBase = pi('lamp_base'); S.cottage = pi('cottage'); S.cottageRoof = pi('cottage_roof'); S.windows = pi('windows');

    let minY = 1e9, maxY = -1e9;
    let lx = 0, ly = 0, lz = 0, ln = 0, gx = 0, gy = 0, gz = 0, gn = 0, rr = 0, ry = 0, rn = 0;
    for (let i = 0, j = 0; i < n; i++, j += 3) {
      const y = P[j + 1];
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
      const p = part[i];
      if (p === S.lamp) { lx += P[j]; ly += y; lz += P[j + 2]; ln++; }
      else if (p === S.glass) { gx += P[j]; gy += y; gz += P[j + 2]; gn++; }
      if (p === S.rocks) { rr += Math.hypot(P[j], P[j + 2]); ry += y; rn++; }
    }
    if (ln > 0) { S.lx = lx / ln; S.ly = ly / ln; S.lz = lz / ln; }
    else if (gn > 0) { S.lx = gx / gn; S.ly = gy / gn; S.lz = gz / gn; }
    else { S.lx = 0; S.ly = maxY * 0.85; S.lz = 0; }
    S.minY = minY; S.maxY = maxY;
    S.waterY = rn > 0 ? minY + (ry / rn - minY) * 0.55 : minY + 0.02;
    S.hRange = Math.max(0.01, maxY - S.waterY);
    const inner = rn > 0 ? (rr / rn) * 1.05 : 0.35;
    S.inner = inner;

    S.modelEnd = Math.floor(n * 0.62);
    S.oceanEnd = Math.floor(n * 0.9);

    // Ocean / beam per-particle layout (reused arrays).
    const A = new Float32Array(n), B = new Float32Array(n), C = new Float32Array(n), D = new Float32Array(n);
    for (let i = S.modelEnd; i < S.oceanEnd; i++) {
      const a = h.rand(i, 11) * Math.PI * 2;
      A[i] = Math.cos(a); B[i] = Math.sin(a);
      C[i] = inner + (3.3 - inner) * Math.pow(h.rand(i, 12), 0.85);
    }
    for (let i = S.oceanEnd; i < n; i++) {
      const a = h.rand(i, 22) * Math.PI * 2;
      const r = Math.sqrt(h.rand(i, 23));
      A[i] = Math.cos(a) * r; B[i] = Math.sin(a) * r;
      C[i] = h.rand(i, 21);
      D[i] = h.rand(i, 24) < 0.5 ? 1 : -1;
    }
    S.A = A; S.B = B; S.C = C; S.D = D;

    S.cloud = new Float32Array(n * 3);
    h.formations.galaxy(S.cloud, n, 24, 3, 2);
    S.ringT = -100; S.ringAmp = 0;

    // Start everything at its target-ish place.
    ctx.setBackground(0.004, 0.008, 0.022);
  },

  update(ctx) {
    const { audio, macros, params, targets, positions, velocities, colors, sizes, alphas, count, helpers } = ctx;
    const S = ctx.state as any;
    const m = ctx.models[MODEL];
    const P = m.positions, N = m.normals, MC = m.colors, part = m.parts;
    const cloud = S.cloud as Float32Array;
    const A = S.A as Float32Array, B = S.B as Float32Array, C = S.C as Float32Array, D = S.D as Float32Array;
    const rocks = S.rocks, tower = S.tower, stripes = S.stripes, gallery = S.gallery, railing = S.railing;
    const glass = S.glass, roof = S.roof, lamp = S.lamp, lampBase = S.lampBase;
    const cottage = S.cottage, cottageRoof = S.cottageRoof, windows = S.windows;
    const modelEnd = S.modelEnd as number, oceanEnd = S.oceanEnd as number;
    const waterY = S.waterY as number, hRange = S.hRange as number;

    const t = ctx.time;
    const s = params.scale;
    const inten = macros.intensity, chaos = macros.chaos;
    const hue = macros.hue, spread = macros.hueSpread;

    if (audio.beat) { S.ringT = t; S.ringAmp = 0.6 + macros.impulse * 1.2; }
    const age = Math.max(0, t - S.ringT);
    const ringR = S.inner * s + age * 16;
    const ringA = S.ringAmp * Math.exp(-age * 0.9) * params.waves;

    // Tower sway (world units at the top).
    const swayAmp = params.sway * (0.3 + inten * 0.7 + audio.bass * 0.6);
    const swayX = Math.sin(t * 0.7) * swayAmp;
    const swayZ = Math.cos(t * 0.53) * swayAmp * 0.6;

    // Lamp position (follows sway).
    const hL = helpers.clamp((S.ly - waterY) / hRange, 0, 1);
    const lampX = S.lx * s + swayX * hL * hL;
    const lampY = S.ly * s;
    const lampZ = S.lz * s + swayZ * hL * hL;
    const axX = S.lx * s, axZ = S.lz * s;

    const theta = t * params.rotate;
    const ct = Math.cos(theta), stn = Math.sin(theta);
    const beamStr = Math.min(1.4, params.glow * (0.35 + audio.mid * 0.6 + audio.pulse * 0.5));
    const L = s * (1.6 + audio.mid * 1.2 + audio.pulse * 0.6) * params.beam;

    const rumble = audio.bass * inten * 0.7;
    const morph = helpers.smoothstep(0, 1, macros.morph);
    const spin = t * 0.15, cs = Math.cos(spin), sn = Math.sin(spin);
    const burst = audio.beat ? 2 + macros.impulse * 5 : 0;
    const galleryF = audio.lowMid * inten * 0.12;
    const roofLift = params.lift * (audio.pulse * (0.5 + macros.impulse * 0.5) + audio.bass * 0.15);
    const cRoofLift = params.lift * audio.bass * inten * 0.35;
    const lampGlow = params.glow * (0.6 + audio.rms * 1.0 + audio.pulse * 0.8);
    const tint = params.tint * (0.6 + spread);
    const chase = t * 0.6;
    const frame = ctx.frame;

    // ---------- Model ----------
    for (let i = 0, j = 0; i < modelEnd; i++, j += 3) {
      const p = part[i];
      const nx = N[j], ny = N[j + 1], nz = N[j + 2];
      let x = P[j] * s, y = P[j + 1] * s, z = P[j + 2] * s;
      const lambert = nx * 0.45 + ny * 0.7 + nz * 0.5;
      const light = 0.3 + 0.7 * (lambert > 0 ? lambert : 0);
      let r = MC[j] * light * 1.1, g = MC[j + 1] * light * 1.1, b = MC[j + 2] * light * 1.1;
      let size = 1, alpha = 0.88;
      let tintable = true, onTower = true;

      if (p === rocks) {
        onTower = false;
        const k = (helpers.rand(i, frame & 15) - 0.5) * rumble;
        x += nx * k; y += ny * k; z += nz * k;
        r *= 0.75; g *= 0.8; b *= 0.95;
      } else if (p === stripes) {
        const hn = (P[j + 1] - waterY) / hRange;
        let band = hn * 3 - chase;
        band = band - Math.floor(band);
        let tri = 1 - Math.abs(band - 0.5) * 2;
        tri = tri * tri * tri * tri;
        helpers.setColorHSL(i, hue + 0.42, 0.85, 0.22 + 0.15 * light + tri * 0.25 * (0.5 + audio.mid) + audio.pulse * 0.12);
        r = colors[j]; g = colors[j + 1]; b = colors[j + 2];
        size = 1 + tri * 0.4;
        tintable = false;
      } else if (p === gallery || p === railing) {
        const dx = x - axX, dz = z - axZ;
        x += dx * galleryF; z += dz * galleryF;
        if (p === railing && helpers.rand(i, frame >> 1) < audio.high * 0.6) {
          r += 0.5; g += 0.5; b += 0.45; size = 1.6; alpha = 1;
        }
      } else if (p === glass) {
        helpers.setColorHSL(i, hue - 0.05, 0.6, 0.2 + audio.mid * 0.35 + audio.pulse * 0.15);
        r = colors[j]; g = colors[j + 1]; b = colors[j + 2];
        alpha = 0.7;
        tintable = false;
        if (burst > 0 && helpers.rand(i, frame & 7) < 0.3) {
          velocities[j] += nx * burst; velocities[j + 1] += ny * burst; velocities[j + 2] += nz * burst;
        }
      } else if (p === lamp) {
        const fl = lampGlow * (0.85 + 0.15 * helpers.rand(i, frame >> 2));
        r = 1.0 * fl; g = 0.85 * fl; b = 0.5 * fl;
        size = 1.5 + audio.rms * 2 + audio.pulse * 1.5;
        alpha = 1;
        tintable = false;
      } else if (p === lampBase) {
        r *= 1.3; g *= 1.2; b *= 0.9;
      } else if (p === roof) {
        y += roofLift;
      } else if (p === cottage) {
        onTower = false;
      } else if (p === cottageRoof) {
        onTower = false;
        y += cRoofLift;
      } else if (p === windows) {
        onTower = false;
        const fl = (0.55 + 0.45 * helpers.rand(i, frame >> 3)) * (0.5 + audio.high * 1.5 + audio.pulse * 0.3);
        r = 0.95 * fl; g = 0.62 * fl; b = 0.25 * fl;
        size = 1.2 + audio.high * 1.2;
        alpha = 1;
        tintable = false;
      } else if (p !== tower) {
        onTower = false;
      }

      if (onTower) {
        const hn = helpers.clamp((P[j + 1] - waterY) / hRange, 0, 1);
        const h2 = hn * hn;
        x += swayX * h2; z += swayZ * h2;
      }

      if (morph > 0) {
        const cx = cloud[j] * cs - cloud[j + 2] * sn, cz = cloud[j] * sn + cloud[j + 2] * cs;
        x += (cx - x) * morph; y += (cloud[j + 1] - y) * morph; z += (cz - z) * morph;
      }
      targets[j] = x; targets[j + 1] = y; targets[j + 2] = z;

      if (tintable && tint > 0) {
        helpers.setColorHSL(i, hue + P[j + 1] * spread * 0.5, 0.6, 0.18 + 0.32 * light);
        r += (colors[j] - r) * tint; g += (colors[j + 1] - g) * tint; b += (colors[j + 2] - b) * tint;
      }
      colors[j] = r; colors[j + 1] = g; colors[j + 2] = b;
      sizes[i] = size * (1 + helpers.rand(i, 5) * 0.6);
      alphas[i] = alpha;
    }

    // ---------- Ocean ----------
    const amp = params.waves * (0.25 + audio.bass * inten * 1.4 + inten * 0.2);
    const wY = waterY * s;
    const noiseAmp = 0.4 + chaos * 0.6;
    for (let i = modelEnd, j = modelEnd * 3; i < oceanEnd; i++, j += 3) {
      const radN = C[i];
      const rad = radN * s;
      const x = A[i] * rad, z = B[i] * rad;
      const nse = helpers.noise3(x * 0.06, z * 0.06, t * 0.25);
      const hgt = (Math.sin(rad * 0.32 - t * 1.4) * 0.5 + Math.sin(x * 0.15 + z * 0.11 + t * 0.8) * 0.35 + nse * noiseAmp) * amp;
      const dr = rad - ringR;
      const ringV = ringA > 0.01 ? ringA * Math.exp(-dr * dr * 0.12) : 0;
      targets[j] = x; targets[j + 1] = wY + hgt + ringV * 1.2; targets[j + 2] = z;

      const crest = helpers.clamp(hgt / (amp + 0.001) * 0.5 + 0.5, 0, 1);
      const d = A[i] * ct + B[i] * stn;
      const d2 = d * d;
      let illum = d2 > 0.97 ? (d2 - 0.97) / 0.03 : 0;
      if (illum > 0) illum *= beamStr * helpers.clamp(1.2 - rad / (L * 1.3 + 0.001), 0, 1);
      helpers.setColorHSL(i, hue + 0.02 - crest * 0.05 * (0.3 + spread), 0.7 - illum * 0.4, 0.06 + crest * crest * 0.14 + illum * 0.42 + ringV * 0.1);
      const fade = 1 - helpers.smoothstep(2.5, 3.3, radN);
      alphas[i] = (0.45 + crest * 0.25 + illum * 0.3) * fade;
      sizes[i] = 0.9 + illum * 0.8 + crest * 0.3;
    }

    // ---------- Beams ----------
    const px = -stn, pz = ct;
    const widthK = 0.07 + chaos * 0.02;
    for (let i = oceanEnd, j = oceanEnd * 3; i < count; i++, j += 3) {
      const u = C[i];
      const side = D[i];
      const dist = u * L;
      const w = widthK * dist + 0.25;
      const bx = A[i], by = B[i];
      targets[j] = lampX + ct * side * dist + px * bx * w;
      targets[j + 1] = lampY - 0.04 * dist + by * w * 0.6;
      targets[j + 2] = lampZ + stn * side * dist + pz * bx * w;
      const fall = 1 - u;
      const core = 1 - Math.min(1, bx * bx + by * by);
      const l = beamStr * fall * (0.35 + 0.65 * core);
      colors[j] = 0.95 * l; colors[j + 1] = 0.82 * l; colors[j + 2] = 0.55 * l;
      alphas[i] = fall * 0.7;
      sizes[i] = 1.1 + u * 0.9;
    }

    ctx.integrate({
      spring: 8 + inten * 3,
      damping: 3.2,
      flow: chaos * 2,
      flowScale: 0.25,
      maxSpeed: 40,
    });

    // Ocean and beams are placed exactly (crisp sweep, no lag).
    for (let k = modelEnd * 3, e = count * 3; k < e; k++) {
      positions[k] = targets[k];
      velocities[k] = 0;
    }
  },
};

